<file path="src/credits.js">
import { ok, fail } from './result.js';
import { invoiceTotals } from './invoices.js';

/**
 * Get the next free credit note number for a given issue date.
 * Format: CN-YYYY-NNNN where NNNN restarts at 0001 each year.
 * @param {Array<string>} existingNumbers - Invoice and credit note numbers, in any order
 * @param {string} issueDate - Date in YYYY-MM-DD format
 * @returns {string}
 */
function nextCreditNoteNumber(existingNumbers, issueDate) {
  const year = issueDate.substring(0, 4);

  // Filter credit note numbers for this year
  const thisYearPattern = new RegExp(`^CN-${year}-\\d{4}$`);
  const thisYearNumbers = existingNumbers.filter((n) => thisYearPattern.test(n));

  // Extract counters and find max
  const counters = thisYearNumbers.map((n) => parseInt(n.substring(n.lastIndexOf('-') + 1), 10));
  const maxCounter = counters.length > 0 ? Math.max(...counters) : 0;

  // Return next counter
  const nextCounter = maxCounter + 1;
  return `CN-${year}-${String(nextCounter).padStart(4, '0')}`;
}

/**
 * Create a credit note for an issued invoice.
 * @param {{ status: string, number: string, customerId: string, lines: Array<any> }, { amount: number, reason: string, date: string }, Array<string> }
 */
export function createCreditNote(invoice, { amount, reason, date }, existingNumbers) {
  // Check status
  if (invoice.status === 'draft') return fail('NOT_ISSUED');

  // Validate amount
  if (!Number.isInteger(amount) || amount <= 0) {
    return fail('AMOUNT_INVALID');
  }

  // Check credit amount doesn't exceed invoice total
  const invoiceTotal = invoiceTotals(invoice).total;
  if (amount > invoiceTotal) {
    return fail('CREDIT_TOO_HIGH');
  }

  // Get next credit note number
  const number = nextCreditNoteNumber(existingNumbers, date);

  return ok({
    number,
    invoiceNumber: invoice.number,
    customerId: invoice.customerId,
    amount,
    reason,
    date,
  });
}
</file>

<file path="src/customers.js">
import { readFileSync } from 'node:fs';
import { ok, fail } from './result.js';

const CUSTOMERS = JSON.parse(readFileSync(new URL('../data/customers.json', import.meta.url), 'utf8'));

/** Default discount percentages by customer tier. */
export const TIER_DISCOUNTS = {
  gold: 5,
  silver: 2.5,
  standard: 0,
};

/**
 * Normalize a customer ID: trim whitespace and convert to uppercase.
 * @param {string} id
 * @returns {string}
 */
export function normalizeId(id) {
  return String(id).trim().toUpperCase();
}

/**
 * All customers: { id, name, email, country, tier }.
 */
export function listCustomers() {
  return CUSTOMERS.map((c) => ({ ...c }));
}

/**
 * One customer by id.
 * @param {string} id
 */
export function getCustomer(id) {
  const normalizedId = normalizeId(id);
  const c = CUSTOMERS.find((x) => x.id === normalizedId);
  return c ? ok({ ...c }) : fail('CUSTOMER_NOT_FOUND');
}

/**
 * Check a customer record before it is stored.
 * @param {{ id?: string, name?: string, email?: string }} c
 */
export function validateCustomer(c) {
  if (!c || !c.id || !c.name || !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(c.email ?? '')) return fail('CUSTOMER_INVALID');
  return ok({ ...c });
}
</file>

<file path="src/dates.js">
/**
 * Check if text is a valid date in YYYY-MM-DD format.
 * @param {string} text
 * @returns {boolean}
 */
export function isValidDate(text) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(String(text))) return false;

  const parts = String(text).split('-').map(Number);
  const [year, month, day] = parts;

  // Create date in UTC and verify it matches the input
  const date = new Date(Date.UTC(year, month - 1, day));
  return date.getUTCFullYear() === year && date.getUTCMonth() === month - 1 && date.getUTCDate() === day;
}

/**
 * Add n days to a date string. Works in UTC.
 * @param {string} date - Date in YYYY-MM-DD format
 * @param {number} n - Number of days to add
 * @returns {string} - Date in YYYY-MM-DD format
 */
export function addDays(date, n) {
  const parts = date.split('-').map(Number);
  const [year, month, day] = parts;

  const d = new Date(Date.UTC(year, month - 1, day));
  d.setUTCDate(d.getUTCDate() + n);

  const y = d.getUTCFullYear();
  const m = String(d.getUTCMonth() + 1).padStart(2, '0');
  const resultDay = String(d.getUTCDate()).padStart(2, '0');

  return `${y}-${m}-${resultDay}`;
}

/**
 * Calculate days between two dates. Works in UTC.
 * @param {string} a - First date in YYYY-MM-DD format
 * @param {string} b - Second date in YYYY-MM-DD format
 * @returns {number} - Number of days (b - a), positive if b is later, negative if earlier
 */
export function daysBetween(a, b) {
  const partsA = a.split('-').map(Number);
  const partsB = b.split('-').map(Number);

  const date1 = new Date(Date.UTC(partsA[0], partsA[1] - 1, partsA[2]));
  const date2 = new Date(Date.UTC(partsB[0], partsB[1] - 1, partsB[2]));

  const diff = date2 - date1;
  return Math.floor(diff / (1000 * 60 * 60 * 24));
}
</file>

